-- Technika 6.0 independent project: schema, access control and storage.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,role text not null default 'visitor' check(role in ('visitor','admin')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.event_categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,description text,created_at timestamptz not null default now());
create table if not exists public.events(id uuid primary key default gen_random_uuid(),category_id uuid references public.event_categories(id) on delete set null,title text not null,slug text not null unique,description text,event_date date,start_time time,end_time time,venue text,image_path text,registration_url text,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint valid_event_time check(end_time is null or start_time is null or end_time>start_time));
create table if not exists public.event_schedules(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,starts_at timestamptz,ends_at timestamptz,venue text,created_at timestamptz not null default now(),constraint valid_schedule_range check(ends_at is null or starts_at is null or ends_at>starts_at));
create table if not exists public.event_bookmarks(user_id uuid not null references auth.users(id) on delete cascade,event_id uuid not null references public.events(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,event_id));
create table if not exists public.faqs(id uuid primary key default gen_random_uuid(),question text not null,answer text not null,category text,sort_order integer not null default 0,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.contact_messages(id uuid primary key default gen_random_uuid(),name text not null,email text not null,subject text not null,message text not null,status text not null default 'new' check(status in('new','read','resolved')),created_at timestamptz not null default now());
create table if not exists public.content_sources(id uuid primary key default gen_random_uuid(),entity_type text not null,entity_id uuid,source_url text not null,verification_note text,checked_at timestamptz,created_at timestamptz not null default now());
create index if not exists events_category_idx on public.events(category_id);create index if not exists events_published_date_idx on public.events(is_published,event_date);create index if not exists events_title_search_idx on public.events using gin(to_tsvector('english',coalesce(title,'')||' '||coalesce(description,'')));create index if not exists schedules_start_idx on public.event_schedules(starts_at);create index if not exists bookmarks_user_idx on public.event_bookmarks(user_id);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end $$;
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at();create trigger events_updated before update on public.events for each row execute function public.set_updated_at();create trigger faqs_updated before update on public.faqs for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,new.raw_user_meta_data->>'display_name');return new;end $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
-- Prevent self-promotion by blocking role changes unless the caller is already an admin.
create or replace function public.protect_profile_role() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.role is distinct from new.role and not public.is_admin() then raise exception 'Only an administrator can change account roles'; end if; return new; end $$;
drop trigger if exists protect_profile_role_trigger on public.profiles;
create trigger protect_profile_role_trigger before update on public.profiles for each row execute function public.protect_profile_role();
-- Atomic sliding-window counter for contact form submissions, keyed by hashed client IP.
create table if not exists public.contact_rate_limits(ip_hash text primary key,window_started_at timestamptz not null default now(),attempts integer not null default 1);
alter table public.contact_rate_limits enable row level security;
create or replace function public.consume_contact_rate_limit(p_ip_hash text) returns boolean language plpgsql security definer set search_path=public as $$ declare current_row public.contact_rate_limits%rowtype; begin insert into public.contact_rate_limits(ip_hash,window_started_at,attempts) values(p_ip_hash,now(),1) on conflict(ip_hash) do update set attempts=case when public.contact_rate_limits.window_started_at < now()-interval '10 minutes' then 1 else public.contact_rate_limits.attempts+1 end, window_started_at=case when public.contact_rate_limits.window_started_at < now()-interval '10 minutes' then now() else public.contact_rate_limits.window_started_at end returning * into current_row; return current_row.attempts <= 5; end $$;
revoke all on function public.consume_contact_rate_limit(text) from public, anon, authenticated;
grant execute on function public.consume_contact_rate_limit(text) to service_role;
-- Role field is intentionally excluded from user-editable profile policy.
alter table public.profiles enable row level security;alter table public.event_categories enable row level security;alter table public.events enable row level security;alter table public.event_schedules enable row level security;alter table public.event_bookmarks enable row level security;alter table public.faqs enable row level security;alter table public.contact_messages enable row level security;alter table public.content_sources enable row level security;
create policy profiles_select_own on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());create policy profiles_update_own on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());create policy profiles_admin_all on public.profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy categories_public_read on public.event_categories for select to anon,authenticated using(true);create policy categories_admin_write on public.event_categories for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy events_public_read on public.events for select to anon,authenticated using(is_published or public.is_admin());create policy events_admin_write on public.events for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy schedules_public_read on public.event_schedules for select to anon,authenticated using(exists(select 1 from public.events e where e.id=event_id and (e.is_published or public.is_admin())));create policy schedules_admin_write on public.event_schedules for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy bookmarks_read_own on public.event_bookmarks for select to authenticated using(user_id=auth.uid() or public.is_admin());create policy bookmarks_insert_own on public.event_bookmarks for insert to authenticated with check(user_id=auth.uid());create policy bookmarks_delete_own on public.event_bookmarks for delete to authenticated using(user_id=auth.uid());
create policy faqs_public_read on public.faqs for select to anon,authenticated using(is_published or public.is_admin());create policy faqs_admin_write on public.faqs for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy contact_admin_read on public.contact_messages for select to authenticated using(public.is_admin());create policy contact_admin_update on public.contact_messages for update to authenticated using(public.is_admin()) with check(public.is_admin());create policy sources_admin_only on public.content_sources for all to authenticated using(public.is_admin()) with check(public.is_admin());
-- No public insert policy for contact_messages: Edge Function performs validation and privileged insert server-side.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('event-media','event-media',true,5242880,array['image/jpeg','image/png','image/webp','image/avif']) on conflict(id) do nothing;
create policy event_media_public_read on storage.objects for select to anon,authenticated using(bucket_id='event-media');create policy event_media_admin_insert on storage.objects for insert to authenticated with check(bucket_id='event-media' and public.is_admin());create policy event_media_admin_update on storage.objects for update to authenticated using(bucket_id='event-media' and public.is_admin()) with check(bucket_id='event-media' and public.is_admin());create policy event_media_admin_delete on storage.objects for delete to authenticated using(bucket_id='event-media' and public.is_admin());
